const fn = new Function(code + "\nreturn { planLayout, place };");
const { planLayout, place } = fn();
const cols = planLayout(["a", "b", "c", "d", "e"], 2);
if (cols.length !== 2) throw new Error("Two column buckets.");
if (cols[0].join() !== "a,c,e" || cols[1].join() !== "b,d") throw new Error("Row-major: a b / c d / e — column 0 gets a,c,e.");

const fn = new Function(code + "\nreturn { planLayout, place };");
