if (place(["a","b","c","d","e"], 2, 3).row !== 1 || place(["a","b","c","d","e"], 2, 3).col !== 1) throw new Error("Index 3 at 2 cols: row 1, col 1.");
if (place(["a","b","c","d","e"], 3, 4).row !== 1 || place(["a","b","c","d","e"], 3, 4).col !== 1) throw new Error("Index 4 at 3 cols: row 1, col 1.");
